// Usado pela tela Rotativo do Setup da Conta para ler e gravar a lista.
// Só responde com a chave certa (gerada para esta conta).
const CHAVE = "__ROTATIVO_CHAVE__";
const INICIAL = ["__ORDEM_ROTATIVO__"];

const body = $('Webhook config').first().json.body || {};
if (body.chave !== CHAVE) return [{ json: { ok: false, erro: 'chave inválida' } }];

const memoria = $getWorkflowStaticData('global');
if (!Array.isArray(memoria.lista)) memoria.lista = INICIAL;
if (body.acao === 'salvar' && Array.isArray(body.lista)) {
  memoria.lista = body.lista
    .filter((p) => p && typeof p.id === 'string')
    .map((p) => ({ id: p.id, nome: String(p.nome || '').slice(0, 100), ligado: Boolean(p.ligado), peso: Math.max(1, Math.min(10, Math.round(Number(p.peso) || 1))) }));
}
// Transbordo: { ligado, minutos } (a tela só manda quando o fluxo tem transbordo).
if (body.acao === 'salvar' && body.transbordo && typeof body.transbordo === 'object') {
  const m = Number(body.transbordo.minutos) || Number(body.transbordo.horas) * 60;
  memoria.transbordo = { ligado: Boolean(body.transbordo.ligado), minutos: m > 0 ? Math.min(Math.max(Math.round(m), 1), 10080) : 180, criterio: body.transbordo.criterio === 'assumiu' ? 'assumiu' : 'resposta' };
}
return [{ json: { ok: true, lista: memoria.lista, ultimo: memoria.ultimo || null, versao: 3, transbordo: memoria.transbordo || { ligado: false, minutos: 180, criterio: 'resposta' } } }];

// Transbordo do rotativo: ligar/desligar, o tempo (em minutos) e o critério de
// "atendida" vêm da tela Rotativo do Setup da Conta.
const memoria = $getWorkflowStaticData('global');
const t = memoria.transbordo || {};
if (!t.ligado) return [];
const minutos = Number(t.minutos) > 0 ? Number(t.minutos) : Number(t.horas) > 0 ? Number(t.horas) * 60 : 180;
// 'resposta' = o atendente mandou mensagem; 'assumiu' = a conversa está com alguém.
const criterio = t.criterio === 'assumiu' ? 'assumiu' : 'resposta';
return [{ json: { minutos, criterio } }];

// Transbordo: conversas que o rotativo distribuiu, ninguém assumiu e já passaram
// o tempo configurado → vão para a próxima pessoa ligada da lista (na equipe
// com o nome dela, como o chatbot faz). Só roda dentro do horário de atendimento.
const memoria = $getWorkflowStaticData('global');
const { minutos, criterio } = $('Transbordo ligado?').first().json;
const fila = (Array.isArray(memoria.lista) ? memoria.lista : []).filter((p) => p.ligado && p.nome);
if (fila.length < 2) return [];

// Horário de atendimento da conta (dias como MONDAY..SUNDAY ou 0..6, 0 = domingo).
const oh = $('Horário de atendimento').first().json || {};
if (oh.limitHours && Array.isArray(oh.days) && oh.days.length) {
  let diff = Number.isFinite(Number(oh.timezoneDiff)) ? Number(oh.timezoneDiff) : -3;
  if (Math.abs(diff) > 14) diff = diff / 60; // veio em minutos
  const local = new Date(Date.now() + diff * 3600000);
  const NOMES = ['SUNDAY', 'MONDAY', 'TUESDAY', 'WEDNESDAY', 'THURSDAY', 'FRIDAY', 'SATURDAY'];
  const d = local.getUTCDay();
  const dia = oh.days.find((x) => { const k = String(x.dayWeek ?? '').toUpperCase(); return k === NOMES[d] || k === String(d); });
  const hm = local.toISOString().slice(11, 16);
  const aberto = !dia || (dia.active !== false && (dia.periods || []).some((p) => String(p.startTime).slice(0, 5) <= hm && hm < String(p.endTime).slice(0, 5)));
  if (!aberto) return [];
}

const agora = Date.now();
const sessoes = $('Conversas abertas').first().json.items || [];
const equipes = $('Equipes').first().json.body || [];
const norm = (s) => String(s || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').trim().replace(/\s+/g, ' ').toLowerCase();
const equipePorNome = new Map(equipes.map((e) => [norm(e.name), e.id]));
const ids = fila.map((p) => p.id);
const out = [];
for (const s of sessoes) {
  const m = s.metadata || {};
  if (!m.rotativoEm) continue; // não veio do rotativo
  if (criterio === 'assumiu' && s.userId) continue; // alguém já assumiu
  const em = Date.parse(m.rotativoEm);
  if (!em || agora - em < minutos * 60000) continue;
  const proximo = fila[(ids.indexOf(m.rotativoUserId) + 1) % fila.length];
  if (!proximo || proximo.id === m.rotativoUserId) continue;
  out.push({ json: {
    sessionId: s.id, contactId: s.contactId, userId: proximo.id, nome: proximo.nome,
    equipeId: equipePorNome.get(norm(proximo.nome)) || null,
    rodadas: (Number(m.rotativoRodadas) || 0) + 1, em: new Date(agora).toISOString(), criterio,
  } });
}
return out;

// Critério "o atendente respondeu": confere nas mensagens de cada conversa
// candidata se uma pessoa já respondeu (mensagem enviada por usuário, não por
// chatbot, API ou mensagem automática). Quem já teve resposta sai do transbordo.
const candidatas = $('Quem transborda').all();
const respostas = $input.all();
const out = [];
candidatas.forEach((c, i) => {
  const cand = c.json;
  if (cand.criterio === 'assumiu') { out.push({ json: cand, pairedItem: { item: i } }); return; }
  const r = respostas[i] && respostas[i].json ? respostas[i].json : {};
  if (r.error) return; // não conseguiu ler as mensagens: não mexe nesta conversa
  const msgs = Array.isArray(r.items) ? r.items : Array.isArray(r) ? r : [];
  const respondeu = msgs.some((m) => m.direction === 'FROM_HUB' && m.userId && (m.origin || 'DEFAULT') === 'DEFAULT' && !['TRANSITION', 'TRACK', 'NOTE'].includes(m.type));
  if (!respondeu) out.push({ json: cand, pairedItem: { item: i } });
});
return out;
